import { test, expect } from '@playwright/test';

test.describe('Table Row Expansion', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/table'); // Replace with the actual URL
  });

  test('should expand a row to show nested details', async ({ page }) => {
    const row = page.getByRole('row', { name: /row identifier/i }); // Replace with actual row identifier
    await row.click();

    const nestedDetails = page.getByRole('region', { name: /nested details/i }); // Replace with actual nested details identifier
    await expect(nestedDetails).toBeVisible();
  });

  test('should collapse the row when clicked again', async ({ page }) => {
    const row = page.getByRole('row', { name: /row identifier/i }); // Replace with actual row identifier
    await row.click(); // Expand the row
    await row.click(); // Collapse the row

    const nestedDetails = page.getByRole('region', { name: /nested details/i }); // Replace with actual nested details identifier
    await expect(nestedDetails).not.toBeVisible();
  });
});
